<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { Box,Boxes,RefreshCw,Save,Server,Settings,ShieldCheck } from 'lucide-vue-next'
import { useAuthStore } from '@/stores/useAuthStore'
type Config={configured:boolean;url?:string;username?:string;insecure?:boolean;enabled?:boolean;credentialId?:string;updatedAt?:string}
type Cluster={cluster:string;name:string;drs_enabled:boolean;ha_enabled:boolean}
type Host={host:string;name:string;connection_state:string;power_state:string}
type VM={vm:string;name:string;power_state:string;cpu_count:number;memory_size_MiB:number}
type Inventory={configured:boolean;url?:string;clusters:Cluster[];hosts:Host[];vms:VM[];fetchedAt?:string}
const auth=useAuthStore(); const config=ref<Config>({configured:false}); const inventory=ref<Inventory>({configured:false,clusters:[],hosts:[],vms:[]})
const tab=ref<'clusters'|'hosts'|'vms'>('clusters'); const showForm=ref(false); const loading=ref(false); const saving=ref(false); const testing=ref(false); const syncing=ref(false); const message=ref(''); const error=ref('')
const form=reactive({url:'',username:'',secret:'',insecure:true,enabled:true})
const headers=()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'})
const total=computed(()=>inventory.value.clusters.length+inventory.value.hosts.length+inventory.value.vms.length)
async function request<T>(path:string,init?:RequestInit){const response=await fetch(path,{...init,headers:headers()});const body=await response.json().catch(()=>({message:'请求失败'}));if(!response.ok)throw new Error((body as {message?:string}).message||`请求失败 (${response.status})`);return body as T}
function apply(data:Config){config.value=data;form.url=data.url||'';form.username=data.username||'';form.insecure=data.insecure??true;form.enabled=data.enabled??true;form.secret='';showForm.value=!data.configured}
async function load(){loading.value=true;error.value='';try{apply(await request<Config>('/api/v1/cmdb/vmware/config'));if(config.value.configured)inventory.value=await request<Inventory>('/api/v1/cmdb/vmware/inventory')}catch(reason){error.value=reason instanceof Error?reason.message:'VMware 数据加载失败'}finally{loading.value=false}}
async function testConnection(){testing.value=true;error.value='';message.value='';try{await request('/api/v1/cmdb/vmware/config/test',{method:'POST',body:JSON.stringify({url:form.url,username:form.username,secret:form.secret,insecure:form.insecure})});message.value='连接测试通过'}catch(reason){error.value=reason instanceof Error?reason.message:'连接测试失败'}finally{testing.value=false}}
async function save(){saving.value=true;error.value='';message.value='';try{apply(await request<Config>('/api/v1/cmdb/vmware/config',{method:'PUT',body:JSON.stringify({url:form.url,username:form.username,secret:form.secret,insecure:form.insecure,enabled:form.enabled})}));message.value='VMware 集成配置已保存';await load()}catch(reason){error.value=reason instanceof Error?reason.message:'保存失败'}finally{saving.value=false}}
async function sync(){syncing.value=true;error.value='';message.value='';try{const result=await request<{clusters:number;hosts:number;vms:number}>('/api/v1/cmdb/vmware/sync',{method:'POST'});message.value=`已同步集群 ${result.clusters}、ESXi 主机 ${result.hosts}、虚拟机 ${result.vms}`;await load()}catch(reason){error.value=reason instanceof Error?reason.message:'VMware 同步失败'}finally{syncing.value=false}}
function stateLabel(value:string){return ({CONNECTED:'已连接',DISCONNECTED:'已断开',NOT_RESPONDING:'无响应',POWERED_ON:'运行中',POWERED_OFF:'已关机',SUSPENDED:'已挂起'} as Record<string,string>)[value]||value}
onMounted(load)
</script>
<template>
<section class="vmware-panel">
<header><div><span>INTEGRATION / VMWARE</span><h2>VMware vCenter 资源同步</h2><p>同步虚拟化集群、ESXi 主机和虚拟机到 CMDB，凭据保存到 Vault。</p></div><div><button @click="showForm=!showForm"><Settings/>{{showForm?'收起配置':'配置连接'}}</button><button :disabled="loading" @click="load"><RefreshCw :class="{spin:loading}"/>刷新</button><button class="primary" :disabled="syncing||!config.configured" @click="sync"><Boxes/>同步到 CMDB</button></div></header>
<div v-if="error" class="vmware-error">{{error}}</div><div v-if="message" class="vmware-message">{{message}}</div>
<form v-if="showForm" class="vmware-form" @submit.prevent="save"><div class="form-heading"><ShieldCheck/><div><strong>vCenter 连接配置</strong><span>密码保存在 Vault，数据库只保存 credentialId。</span></div></div><div class="form-grid"><label class="wide"><span>vCenter 地址 *</span><input v-model="form.url" placeholder="https://vcenter.example.com"></label><label><span>用户名</span><input v-model="form.username" placeholder="administrator@vsphere.local"></label><label><span>密码</span><input v-model="form.secret" type="password" :placeholder="config.credentialId?'留空继续使用已保存凭据':'请输入密码'"></label><label class="check"><input v-model="form.insecure" type="checkbox"><span>跳过 TLS 证书校验</span></label><label class="check"><input v-model="form.enabled" type="checkbox"><span>启用 VMware 集成</span></label></div><div class="form-actions"><button type="button" :disabled="testing" @click="testConnection">{{testing?'测试中…':'测试连接'}}</button><button class="primary" :disabled="saving" type="submit"><Save/>{{saving?'保存中…':'保存配置'}}</button></div></form>
<div v-if="!config.configured" class="vmware-empty"><Settings/><strong>VMware vCenter 尚未配置</strong><span>配置地址和凭据后，可预览并同步虚拟化资源。</span></div>
<template v-else><div class="vmware-summary"><span>资源总数</span><strong>{{total}}</strong><span>集群 {{inventory.clusters.length}}</span><span>ESXi {{inventory.hosts.length}}</span><span>虚拟机 {{inventory.vms.length}}</span><small>{{inventory.fetchedAt||config.updatedAt}}</small></div><nav class="vmware-tabs"><button :class="{active:tab==='clusters'}" @click="tab='clusters'"><Boxes/>集群</button><button :class="{active:tab==='hosts'}" @click="tab='hosts'"><Server/>ESXi 主机</button><button :class="{active:tab==='vms'}" @click="tab='vms'"><Box/>虚拟机</button></nav><div class="vmware-list"><article v-for="item in inventory.clusters" v-show="tab==='clusters'" :key="item.cluster"><div><strong>{{item.name}}</strong><span>{{item.cluster}}</span></div><em>DRS {{item.drs_enabled?'开':'关'}} · HA {{item.ha_enabled?'开':'关'}}</em></article><article v-for="item in inventory.hosts" v-show="tab==='hosts'" :key="item.host"><div><strong>{{item.name}}</strong><span>{{item.host}}</span></div><em>{{stateLabel(item.connection_state)}} · {{stateLabel(item.power_state)}}</em></article><article v-for="item in inventory.vms" v-show="tab==='vms'" :key="item.vm"><div><strong>{{item.name}}</strong><span>{{item.vm}}</span></div><em>{{stateLabel(item.power_state)}} · {{item.cpu_count}} vCPU · {{item.memory_size_MiB}} MiB</em></article><div v-if="!total" class="vmware-empty">vCenter 未返回资源。</div></div></template>
</section>
</template>
<style scoped>
.vmware-panel{padding:18px;border:1px solid #173b55;border-radius:12px;background:#071925}.vmware-panel>header{display:flex;justify-content:space-between;gap:16px}.vmware-panel header span{color:#22d3ee;font:10px monospace;letter-spacing:.12em}.vmware-panel h2{margin:5px 0}.vmware-panel p{margin:0;color:#7894a8;font-size:11px}.vmware-panel header>div:last-child{display:flex;gap:8px}.vmware-panel button{display:flex;align-items:center;gap:6px;padding:8px 11px;border:1px solid #23455f;background:#0b263b;color:#bdd8e9;cursor:pointer;border-radius:6px}.vmware-panel button.primary{background:#087b9e}.vmware-panel button:disabled{opacity:.45}.vmware-error,.vmware-message{margin-top:12px;padding:9px;border:1px solid #7b3140;background:#351723;color:#ff9cad}.vmware-message{border-color:#155e75;background:#082b38;color:#a5f3fc}.vmware-form{margin-top:14px;padding:14px;border:1px solid #246c98;background:#061620}.form-heading{display:flex;gap:9px;margin-bottom:12px}.form-heading span{display:block;color:#7894a8;font-size:10px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form-grid label{display:grid;gap:5px}.form-grid label.wide{grid-column:1/-1}.form-grid label.check{display:flex;align-items:center}.form-grid input{height:34px;border:1px solid #28536c;background:#031525;color:#d5edf8;padding:0 8px}.form-actions{display:flex;justify-content:flex-end;gap:7px;margin-top:12px}.vmware-empty{display:flex;flex-direction:column;align-items:center;gap:7px;margin-top:14px;padding:30px;border:1px dashed #1b4258;color:#64748b}.vmware-summary{display:grid;grid-template-columns:repeat(5,auto 1fr);gap:10px;margin-top:14px;padding:11px;border:1px solid #16445c;background:#061620}.vmware-summary>span{color:#6f91a5}.vmware-summary>strong{color:#a5f3fc}.vmware-summary small{grid-column:1/-1;color:#64748b}.vmware-tabs{display:flex;gap:5px;margin-top:12px}.vmware-tabs button.active{border-color:#22d3ee;color:#22d3ee}.vmware-list{display:grid;gap:8px;margin-top:10px}.vmware-list article{display:flex;justify-content:space-between;padding:11px;border:1px solid #16445c;background:#061620}.vmware-list strong,.vmware-list span{display:block}.vmware-list span{color:#6f91a5;font-size:10px}.vmware-list em{color:#2dd4bf;font-style:normal}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){.vmware-panel>header{flex-direction:column}.form-grid{grid-template-columns:1fr}.form-grid label.wide{grid-column:auto}}
</style>
